const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '一元二次方程求根公式图示' },
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: 'x²' },
      { kind: 'text', payload: '−4' },
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: '+' },
      { kind: 'text', payload: '4' },
      { kind: 'text', payload: '= 0' },
      { kind: 'text', payload: 'a = 1' },
      { kind: 'text', payload: 'b = −4' },
      { kind: 'text', payload: 'c = 4' },
      { kind: 'text', payload: '求根公式' },
      { kind: 'text', payload: 'x =' },
      { kind: 'text', payload: '−b ± √(b² − 4ac)' },
      { kind: 'text', payload: '2a' },
      { kind: 'text', payload: 'Δ = b² − 4ac = 0' }
    ];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var dark = '#1F2937';
    var blue = '#2563EB';
    var orange = '#EA580C';
    var green = '#16A34A';
    var amber = '#D97706';
    var amberDark = '#92400E';
    var white = '#FFFFFF';
    function rect(x, y, ww, hh) {
      return [['M', x, y], ['L', x + ww, y], ['L', x + ww, y + hh], ['L', x, y + hh], ['Z']];
    }
    function line(x1, y1, x2, y2) {
      return [['M', x1, y1], ['L', x2, y2]];
    }
    var titleY = h * 0.055;
    var eqY = h * 0.18;
    var boxH = Math.max(32, Math.min(44, h * 0.075));
    var boxTop = eqY - boxH / 2;
    var boxBottom = eqY + boxH / 2;
    var aX = w * 0.19;
    var x2X = w * 0.255;
    var bX = w * 0.375;
    var xX = w * 0.445;
    var plusX = w * 0.505;
    var cX = w * 0.57;
    var zeroX = w * 0.66;
    var aBoxW = 44;
    var bBoxW = 56;
    var cBoxW = 44;
    var calloutY = h * 0.31;
    var barY = h * 0.50;
    var formulaTitleY = barY - h * 0.14;
    var numY = barY - 14;
    var denY = barY + 14;
    var discW = Math.min(w * 0.48, 380);
    var discH = Math.max(48, Math.min(70, h * 0.11));
    var discX = (w - discW) / 2;
    var discY = h * 0.73;
    var paths = [
      { id: 'box-a', commands: rect(aX - aBoxW / 2, boxTop, aBoxW, boxH) },
      { id: 'box-b', commands: rect(bX - bBoxW / 2, boxTop, bBoxW, boxH) },
      { id: 'box-c', commands: rect(cX - cBoxW / 2, boxTop, cBoxW, boxH) },
      { id: 'lead-a', commands: line(aX, boxBottom + 4, aX, calloutY - 6) },
      { id: 'lead-b', commands: line(bX, boxBottom + 4, bX, calloutY - 6) },
      { id: 'lead-c', commands: line(cX, boxBottom + 4, cX, calloutY - 6) },
      { id: 'fraction-bar', commands: line(w * 0.36, barY, w * 0.70, barY) },
      { id: 'disc-outer', commands: rect(discX, discY, discW, discH) },
      { id: 'disc-inner', commands: rect(discX + 3, discY + 3, discW - 6, discH - 6) }
    ];
    var children = [
      { type: 'path', pathId: 'box-a', fill: blue },
      { type: 'path', pathId: 'box-b', fill: orange },
      { type: 'path', pathId: 'box-c', fill: green },
      { type: 'path', pathId: 'lead-a', fill: blue, stroke: { width: 3 } },
      { type: 'path', pathId: 'lead-b', fill: orange, stroke: { width: 3 } },
      { type: 'path', pathId: 'lead-c', fill: green, stroke: { width: 3 } },
      { type: 'path', pathId: 'fraction-bar', fill: dark, stroke: { width: 3 } },
      { type: 'path', pathId: 'disc-outer', fill: amber },
      { type: 'path', pathId: 'disc-inner', fill: '#FFFBEB' },
      { type: 'label', contentId: metrics[0].contentId, anchor: { x: w / 2, y: titleY }, hAlign: 'center', vAlign: 'top', color: dark },
      { type: 'label', contentId: metrics[1].contentId, anchor: { x: aX, y: eqY }, hAlign: 'center', vAlign: 'middle', color: white },
      { type: 'label', contentId: metrics[2].contentId, anchor: { x: x2X, y: eqY }, hAlign: 'center', vAlign: 'middle', color: dark },
      { type: 'label', contentId: metrics[3].contentId, anchor: { x: bX, y: eqY }, hAlign: 'center', vAlign: 'middle', color: white },
      { type: 'label', contentId: metrics[4].contentId, anchor: { x: xX, y: eqY }, hAlign: 'center', vAlign: 'middle', color: dark },
      { type: 'label', contentId: metrics[5].contentId, anchor: { x: plusX, y: eqY }, hAlign: 'center', vAlign: 'middle', color: dark },
      { type: 'label', contentId: metrics[6].contentId, anchor: { x: cX, y: eqY }, hAlign: 'center', vAlign: 'middle', color: white },
      { type: 'label', contentId: metrics[7].contentId, anchor: { x: zeroX, y: eqY }, hAlign: 'left', vAlign: 'middle', color: dark },
      { type: 'label', contentId: metrics[8].contentId, anchor: { x: aX, y: calloutY }, hAlign: 'center', vAlign: 'top', color: blue },
      { type: 'label', contentId: metrics[9].contentId, anchor: { x: bX, y: calloutY }, hAlign: 'center', vAlign: 'top', color: orange },
      { type: 'label', contentId: metrics[10].contentId, anchor: { x: cX, y: calloutY }, hAlign: 'center', vAlign: 'top', color: green },
      { type: 'label', contentId: metrics[11].contentId, anchor: { x: w * 0.12, y: formulaTitleY }, hAlign: 'left', vAlign: 'top', color: dark },
      { type: 'label', contentId: metrics[12].contentId, anchor: { x: w * 0.20, y: barY }, hAlign: 'center', vAlign: 'middle', color: dark },
      { type: 'label', contentId: metrics[13].contentId, anchor: { x: w * 0.53, y: numY }, hAlign: 'center', vAlign: 'bottom', color: dark },
      { type: 'label', contentId: metrics[14].contentId, anchor: { x: w * 0.53, y: denY }, hAlign: 'center', vAlign: 'top', color: dark },
      { type: 'label', contentId: metrics[15].contentId, anchor: { x: w / 2, y: discY + discH / 2 }, hAlign: 'center', vAlign: 'middle', color: amberDark }
    ];
    return { schemaVersion: 1, sceneId: 'quadratic-formula-transcription', revision: input.revision, viewBox: { x: 0, y: 0, width: w, height: h }, paths: paths, root: { type: 'group', children: children } };
  }
};
